@using sv_95a754bca74c4712a20470e059bf5bc4.Models

<div class="step-indicator">
    @for (int i = 0; i < StepNames.Length; i++)
    {
        var stepIndex = i;
        var isCurrent = stepIndex == CurrentStep;
        var isCompleted = stepIndex < CurrentStep;
        var isFuture = stepIndex > CurrentStep;

        <button class="step @(isCurrent ? "current" : "") @(isCompleted ? "completed" : "") @(isFuture ? "future" : "")"
                disabled="@isFuture"
                @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
            <span class="step-number">
                @if (isCompleted)
                {
                    <span>&#10003;</span>
                }
                else
                {
                    @(stepIndex + 1)
                }
            </span>
            <span class="step-label">@StepNames[stepIndex]</span>
        </button>

        @if (i < StepNames.Length - 1)
        {
            <div class="step-connector @(i < CurrentStep ? "completed" : "")"></div>
        }
    }
</div>

@code {
    private static readonly string[] StepNames =
    [
        "Personal Info",
        "Work History",
        "References",
        "Cover Letter",
        "Review & Submit"
    ];

    [Parameter] public int CurrentStep { get; set; }
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }
}

.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 0.4rem;
    background: none;
    border: none;
    cursor: pointer;
    padding: 0.5rem;
    min-width: 5rem;
    transition: opacity 0.2s;
}

.step:disabled {
    cursor: default;
}

.step-number {
    width: 2.2rem;
    height: 2.2rem;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: 600;
    font-size: 0.9rem;
    border: 2px solid #dee2e6;
    background: #fff;
    color: #6c757d;
    transition: all 0.2s;
}

.step-label {
    font-size: 0.78rem;
    color: #6c757d;
    white-space: nowrap;
    transition: color 0.2s;
}

.step.current .step-number {
    border-color: #0d6efd;
    background: #0d6efd;
    color: #fff;
}

.step.current .step-label {
    color: #0d6efd;
    font-weight: 600;
}

.step.completed .step-number {
    border-color: #198754;
    background: #198754;
    color: #fff;
}

.step.completed .step-label {
    color: #198754;
}

.step.completed:hover .step-number {
    background: #157347;
    border-color: #157347;
}

.step.future .step-number {
    opacity: 0.5;
}

.step.future .step-label {
    opacity: 0.5;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #dee2e6;
    margin: 0 0.25rem;
    margin-bottom: 1.4rem;
    max-width: 4rem;
    transition: background 0.2s;
}

.step-connector.completed {
    background: #198754;
}

